import { z } from 'zod';

import { RewardClaimStatus } from './enums';
import { IsoDateTime, Uuid } from './primitives';

/** A custom reward claim code generated by a customer (table `reward_claims`). */
export const RewardClaim = z.object({
  id: Uuid,
  tenantId: Uuid,
  customerId: Uuid,
  code: z.string().length(6),
  status: RewardClaimStatus,
  createdAt: IsoDateTime,
  givenAt: IsoDateTime.nullable().optional(),
  cancelledAt: IsoDateTime.nullable().optional(),
});
export type RewardClaim = z.infer<typeof RewardClaim>;

/** The active open claim returned by get_my_account. */
export const OpenRewardClaim = z.object({
  id: Uuid,
  code: z.string().length(6),
  status: RewardClaimStatus,
  createdAt: IsoDateTime,
});
export type OpenRewardClaim = z.infer<typeof OpenRewardClaim>;
